const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function waitForDebugger() {
  for (let i = 0; i < 40; i++) {
    try {
      const res = await fetch(`http://127.0.0.1:${PORT}/json/version`);
      if (res.ok) return;
    } catch { /* not up yet */ }
    await sleep(250);
  }
  throw new Error('Chromium debugger never came up');
}

let msgId = 0;
const pending = new Map();
let ws;
const consoleErrors = [];
const badRequests = [];

function send(method, params = {}) {
  return new Promise((resolve, reject) => {
    const id = ++msgId;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
}

async function evaluate(expression) {
  const res = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
  if (res.exceptionDetails) throw new Error('evaluate failed: ' + JSON.stringify(res.exceptionDetails).slice(0, 500));
  return res.result ? res.result.value : undefined;
}

async function shot(name) {
  const res = await send('Page.captureScreenshot', { format: 'jpeg', quality: 80 });
  writeFileSync(OUT + name, Buffer.from(res.data, 'base64'));
  console.log('saved', name);
}

const chrome = spawn(CHROME, [
  '--headless=new', '--no-sandbox', '--disable-gpu', '--hide-scrollbars',
  `--remote-debugging-port=${PORT}`, '--window-size=1280,800', 'about:blank',
], { stdio: 'ignore' });

try {
  await waitForDebugger();
  const target = await (await fetch(`http://127.0.0.1:${PORT}/json/new?${encodeURIComponent(BASE)}`, { method: 'PUT' })).json();
  ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  ws.onmessage = (event) => {
    const msg = JSON.parse(event.data);
    if (msg.id && pending.has(msg.id)) { pending.get(msg.id).resolve(msg.result); pending.delete(msg.id); return; }
    if (msg.method === 'Runtime.exceptionThrown') consoleErrors.push(JSON.stringify(msg.params.exceptionDetails).slice(0, 300));
    if (msg.method === 'Runtime.consoleAPICalled' && msg.params.type === 'error') consoleErrors.push(JSON.stringify(msg.params.args).slice(0, 300));
    if (msg.method === 'Network.requestWillBeSent') {
      const url = msg.params.request.url;
      if (!url.startsWith('http://127.0.0.1:8123') && !url.startsWith('data:')) badRequests.push(url);
    }
    if (msg.method === 'Network.loadingFailed') badRequests.push('FAILED ' + (msg.params.errorText || ''));
  };
  await send('Page.enable');
  await send('Runtime.enable');
  await send('Network.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false });
  await send('Page.navigate', { url: BASE });
  await sleep(1500);

  const seeded = await evaluate(`(async () => {
    localStorage.setItem('leonida-trophy-atlas-v1', JSON.stringify({version:1, earned:[2,3,4,5,8,9,15,19,21,35,42,46,55], counts:{15:120,19:9,35:47}, notes:{15:'Stunts add up fast on the highway runs.'}}));
    location.reload();
    return 'seeded';
  })()`);
  console.log('seed:', seeded);
  await sleep(1500);
  console.log('rows rendered:', await evaluate(`document.querySelectorAll('#trophyList .trophy').length`));
  console.log('header count:', await evaluate(`document.getElementById('earnedCount').textContent`));

  // Shot 1 — cover: checklist with a guide open (Cunning Stunts, counter + sources visible).
  await evaluate(`document.querySelector('[data-guide="15"]').click(); 'ok'`);
  await sleep(400);
  await evaluate(`document.querySelector('[data-id="15"]').scrollIntoView({block:'start'}); 'ok'`);
  await sleep(300);
  await shot('1-checklist.jpg');

  // Shot 2 — roadmap view.
  await evaluate(`document.querySelector('[data-view="roadmap"]').click(); 'ok'`);
  await sleep(500);
  await shot('2-roadmap.jpg');

  // Shot 3 — missables view.
