  await sleep(500);
  await shot('3-missables.jpg');

  // Shot 4 — spoiler setting at work: story filter + spoilers hidden.
  await evaluate(`document.querySelector('[data-view="checklist"]').click(); 'ok'`);
  await sleep(300);
  await evaluate(`document.getElementById('spoilerBtn').click(); 'ok'`);
  await sleep(300);
  await evaluate(`document.querySelector('[data-kind="story"]').click(); 'ok'`);
  await sleep(400);
  await shot('4-spoiler.jpg');

  console.log('console errors:', JSON.stringify(consoleErrors));
  console.log('off-origin/failed requests:', JSON.stringify(badRequests));
} finally {
  try { ws && ws.close(); } catch {}
  chrome.kill('SIGKILL');
}
console.log('done');
