import { spawn } from 'node:child_process';

const CHROME = process.env.HOME + '/.cache/ms-playwright/chromium-1148/chrome-linux/chrome';
const PORT = 9224;
const BASE = 'http://127.0.0.1:8131/';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let msgId = 0;
const pending = new Map();
let ws;
const errors = [];
function send(method, params = {}) {
  return new Promise((resolve, reject) => {
    const id = ++msgId;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
}
async function evaluate(expression) {
  const res = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
  if (res.exceptionDetails) throw new Error(JSON.stringify(res.exceptionDetails).slice(0, 400));
  return res.result ? res.result.value : undefined;
}
const chrome = spawn(CHROME, ['--headless=new', '--no-sandbox', '--disable-gpu', '--hide-scrollbars',
  `--remote-debugging-port=${PORT}`, '--window-size=1280,800',
  `--user-data-dir=/tmp/fresh-profile-${Date.now()}`, 'about:blank'], { stdio: 'ignore' });
try {
  for (let i = 0; i < 40; i++) { try { const r = await fetch(`http://127.0.0.1:${PORT}/json/version`); if (r.ok) break; } catch {} await sleep(250); }
  const target = await (await fetch(`http://127.0.0.1:${PORT}/json/new?${encodeURIComponent(BASE)}`, { method: 'PUT' })).json();
  ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  ws.onmessage = (event) => {
    const msg = JSON.parse(event.data);
    if (msg.id && pending.has(msg.id)) { pending.get(msg.id).resolve(msg.result); pending.delete(msg.id); return; }
    if (msg.method === 'Runtime.exceptionThrown') errors.push(JSON.stringify(msg.params.exceptionDetails).slice(0, 300));
  };
  await send('Page.enable'); await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false });
  await send('Page.navigate', { url: BASE });
  await sleep(1500);
  console.log('fresh rows:', await evaluate(`document.querySelectorAll('#trophyList .trophy').length`));
  console.log('fresh header:', await evaluate(`document.getElementById('earnedCount').textContent + '/55'`));
  console.log('fresh result count:', await evaluate(`document.getElementById('resultCount').textContent`));
  // Tick trophy 21 (Stick Fiddler), bump counter on 15 twice, reload, confirm persistence.
  await evaluate(`document.querySelector('[data-earned="21"]').click(); 'ok'`);
  await evaluate(`document.querySelector('[data-guide="15"]').click(); 'ok'`);
  await sleep(300);
  await evaluate(`document.querySelector('[data-count="1"][data-id="15"]').click(); 'ok'`);
  await evaluate(`document.querySelector('[data-count="1"][data-id="15"]').click(); 'ok'`);
  await sleep(300);
  console.log('after tick header:', await evaluate(`document.getElementById('earnedCount').textContent`));
  console.log('counter text:', await evaluate(`document.querySelector('.count-num').textContent`));
  await evaluate(`location.reload(); 'ok'`);
  await sleep(1500);
  console.log('persisted header:', await evaluate(`document.getElementById('earnedCount').textContent`));
  console.log('persisted checkbox 21:', await evaluate(`document.querySelector('[data-earned="21"]').checked`));
  await evaluate(`document.querySelector('[data-guide="15"]').click(); 'ok'`);
  await sleep(300);
  console.log('persisted counter:', await evaluate(`document.querySelector('.count-num').textContent`));
  // Filter check: missable chip + search.
  await evaluate(`document.querySelector('[data-kind="missable"]').click(); 'ok'`);
  await sleep(300);
  console.log('missable filter rows:', await evaluate(`document.querySelectorAll('#trophyList .trophy').length`));
  console.log('console errors:', JSON.stringify(errors));
} finally { try { ws && ws.close(); } catch {} chrome.kill('SIGKILL'); }
console.log('fresh check done');
